CREATE TABLE public.deposit_history (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, order_id text UNIQUE NOT NULL, payment_id text UNIQUE, network text NOT NULL, address text, gross_amount numeric(14,2) NOT NULL CHECK(gross_amount>0), fee_amount numeric(14,2) NOT NULL, fee_rate numeric NOT NULL DEFAULT 0.01, net_amount numeric(14,2) NOT NULL, credited_amount numeric(14,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'started' CHECK(status IN ('started','pending','confirming','completed','cancelled','failed','expired','partial')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), analytics_reported boolean NOT NULL DEFAULT false
);
GRANT SELECT ON public.deposit_history TO authenticated;
GRANT ALL ON public.deposit_history TO service_role;
ALTER TABLE public.deposit_history ENABLE ROW LEVEL SECURITY;
CREATE POLICY deposit_history_owner_read ON public.deposit_history FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE INDEX deposit_history_user_date ON public.deposit_history(user_id,created_at DESC);
INSERT INTO public.deposit_history(user_id,order_id,payment_id,network,gross_amount,fee_amount,fee_rate,net_amount,credited_amount,status,created_at,analytics_reported)
 SELECT d.user_id,'legacy-'||d.id,d.reference,'unknown',d.amount+coalesce(f.fee,0),coalesce(f.fee,0),CASE WHEN d.amount+coalesce(f.fee,0)>0 THEN coalesce(f.fee,0)/(d.amount+coalesce(f.fee,0)) ELSE 0 END,d.amount,d.amount,'completed',d.created_at,true FROM public.wallet_transactions d LEFT JOIN LATERAL (SELECT sum(abs(amount)) fee FROM public.wallet_transactions WHERE user_id=d.user_id AND reference=d.reference AND type='fee') f ON true WHERE d.type='deposit' AND d.amount>0 ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.cancel_deposit(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.deposit_history SET status='cancelled',updated_at=now() WHERE id=_id AND user_id=auth.uid() AND status IN ('started','pending'); IF NOT FOUND THEN RAISE EXCEPTION 'Deposit cannot be cancelled'; END IF; END; $$;
REVOKE ALL ON FUNCTION public.cancel_deposit(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.cancel_deposit(uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.claim_deposit_analytics() RETURNS SETOF public.deposit_history LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ UPDATE public.deposit_history SET analytics_reported=true WHERE user_id=auth.uid() AND status='completed' AND analytics_reported=false RETURNING *; $$;
REVOKE ALL ON FUNCTION public.claim_deposit_analytics() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.claim_deposit_analytics() TO authenticated;
CREATE OR REPLACE FUNCTION public.credit_deposit(_user_id uuid,_amount numeric,_reference text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _fee numeric; _net numeric; BEGIN IF _amount IS NULL OR _amount<=0 THEN RAISE EXCEPTION 'Invalid amount'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_reference,0)); IF EXISTS(SELECT 1 FROM public.wallet_transactions WHERE reference=_reference AND type='deposit') THEN RETURN; END IF; _fee:=round(_amount*0.01,2); _net:=greatest(_amount-_fee,0); UPDATE public.wallets SET balance=balance+_net,updated_at=now() WHERE user_id=_user_id; IF NOT FOUND THEN RAISE EXCEPTION 'Wallet not found'; END IF; INSERT INTO public.wallet_transactions(user_id,type,amount,reference) VALUES(_user_id,'deposit',_net,_reference); IF _fee>0 THEN INSERT INTO public.wallet_transactions(user_id,type,amount,reference) VALUES(_user_id,'fee',-_fee,_reference); END IF; UPDATE public.deposit_history SET gross_amount=_amount,fee_amount=_fee,net_amount=_net,credited_amount=_net,status='completed',updated_at=now() WHERE payment_id=_reference AND user_id=_user_id; END; $$;
REVOKE ALL ON FUNCTION public.credit_deposit(uuid,numeric,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.credit_deposit(uuid,numeric,text) TO service_role;